// handoff/design_handoff_semester_launch/live.js
try { (() => {
// Live mode for the platform shell: real Supabase Auth + grants read under RLS. Fails closed.
// Only the project URL and the publishable (anon) key are entered here — both are designed to be public. Never paste a service-role key.
(function () {
  const LK = 'sem-live',
    SDK = 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/dist/umd/supabase.js';
  let cfg = JSON.parse(localStorage.getItem(LK) || 'null');
  let sb = null,
    session = null,
    grants = null,
    caps = [],
    err = '';
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;'
  })[c]);
  const load = () => new Promise((ok, no) => {
    if (window.supabase) return ok();
    const s = document.createElement('script');
    s.src = SDK;
    s.onload = ok;
    s.onerror = () => no(new Error('Could not load the Supabase SDK'));
    document.head.appendChild(s);
  });
  async function connect() {
    if (!cfg) return;
    await load();
    sb = window.supabase.createClient(cfg.url, cfg.key, {
      auth: {
        persistSession: true,
        storageKey: 'sem-live-auth'
      }
    });
    const {
      data
    } = await sb.auth.getSession();
    session = data.session;
    sb.auth.onAuthStateChange((_e, s) => {
      session = s;
      refresh();
    });
    await refresh();
  }
  async function refresh() {
    grants = null;
    caps = [];
    err = '';
    if (session) {
      const g = await sb.from('live_workspace_grants').select('workspace,institution_id,valid_until');
      if (g.error) {
        err = g.error.code === '42P01' || /does not exist/.test(g.error.message) ? 'The live_workspace_grants table isn’t in this project yet. Apply handoff/live-integration migration — until then you only get the public workspace.' : 'Grant lookup failed: ' + g.error.message;
        grants = [];
      } else grants = g.data;
      const c = await sb.from('live_tenant_capabilities').select('institution_id,capability,enabled,kill_switch');
      if (!c.error) caps = c.data;
    }
    apply();
  }
  function apply() {
    window.SEM_LIVE = {
      on: !!session,
      user: session && session.user,
      grants: grants || [],
      caps,
      err
    };
    window.dispatchEvent(new Event('sem-live'));
  }
  const ui = () => {
    let d = document.getElementById('lvd');
    if (!d) {
      d = document.createElement('div');
      d.id = 'lvd';
      d.setAttribute('role', 'dialog');
      d.setAttribute('aria-modal', 'true');
      d.setAttribute('aria-label', 'Live connection');
      d.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:60;display:none;padding:8vh 16px';
      document.body.appendChild(d);
      d.onclick = e => {
        if (e.target === d) close();
      };
    }
    return d;
  };
  function close() {
    ui().style.display = 'none';
    document.getElementById('lvb').focus();
  }
  function render() {
    const d = ui();
    const box = c => '<div style="max-width:520px;margin:0 auto;background:var(--surface-base);border:1px solid var(--border-subtle);border-radius:10px;padding:18px;display:grid;gap:10px;box-shadow:0 12px 40px rgba(0,0,0,.25)">' + c + '</div>';
    const f = 'style="display:grid;gap:3px;font-size:12px;color:var(--text-secondary)"';
    if (!cfg) d.innerHTML = box('<h2 style="margin:0;font-size:18px">Connect your Supabase project</h2><p class="muted" style="margin:0">Real sign-in and real grants, read under row-level security. Paste the project URL and the <b>publishable (anon) key</b> from Project Settings → API. Never paste the service-role key.</p><label ' + f + '>Project URL<input id="lvu" placeholder="https://xxxx.supabase.co"></label><label ' + f + '>Publishable key<input id="lvk" placeholder="eyJ… or sb_publishable_…"></label><div id="lve" class="muted" role="alert"></div><div class="row"><button class="btn p" id="lvs">Connect</button><button class="btn" id="lvx">Cancel</button></div>');else if (!session) d.innerHTML = box('<h2 style="margin:0;font-size:18px">Sign in</h2><p class="muted" style="margin:0">' + esc(cfg.url) + '</p><label ' + f + '>Email<input id="lvm" type="email" autocomplete="email"></label><label ' + f + '>Password<input id="lvp" type="password" autocomplete="current-password"></label><div id="lve" class="muted" role="alert"></div><div class="row"><button class="btn p" id="lvi">Sign in</button><button class="btn" id="lvl">Email me a link</button><button class="btn" id="lvf">Disconnect project</button><button class="btn" id="lvx">Cancel</button></div>');else {
      const g = grants || [];
      d.innerHTML = box('<h2 style="margin:0;font-size:18px">Live · ' + esc(session.user.email) + '</h2><div class="muted">' + esc(cfg.url) + '</div>' + (err ? '<div class="note bad">' + esc(err) + '</div>' : '') + '<div><b style="font-size:13px">Your grants</b>' + (g.length ? g.map(x => '<div class="mono">' + esc(x.workspace) + ' · ' + esc(x.institution_id.slice(0, 8)) + '…' + (x.valid_until ? ' · until ' + esc(x.valid_until.slice(0, 10)) : '') + '</div>').join('') : '<div class="muted">None — you see the public workspace only.</div>') + '</div><div><b style="font-size:13px">Enabled capabilities</b>' + (caps.filter(c => c.enabled && !c.kill_switch).map(c => '<div class="mono">' + esc(c.capability) + '</div>').join('') || '<div class="muted">None enabled. Every live function will refuse.</div>') + '</div><div class="row"><button class="btn" id="lvo">Sign out</button><button class="btn" id="lvx">Close</button></div>');
    }
    const g = id => document.getElementById(id),
      e = t => {
        g('lve').textContent = t;
      };
    if (g('lvx')) g('lvx').onclick = close;
    if (g('lvs')) g('lvs').onclick = async () => {
      const url = g('lvu').value.trim().replace(/\/$/, ''),
        key = g('lvk').value.trim();
      if (!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(url)) return e('Use your https://<ref>.supabase.co URL.');
      try {
        const p = JSON.parse(atob(key.split('.')[1] || ''));
        if (p.role === 'service_role') return e('That’s a service-role key. It bypasses all security — rotate it now and use the publishable key.');
      } catch (_) {}
      if (!key) return e('Add the publishable key.');
      cfg = {
        url,
        key
      };
      localStorage.setItem(LK, JSON.stringify(cfg));
      try {
        await connect();
        render();
      } catch (x) {
        e(x.message);
      }
    };
    if (g('lvi')) g('lvi').onclick = async () => {
      const {
        error
      } = await sb.auth.signInWithPassword({
        email: g('lvm').value.trim(),
        password: g('lvp').value
      });
      if (error) return e(error.message);
      render();
    };
    if (g('lvl')) g('lvl').onclick = async () => {
      const {
        error
      } = await sb.auth.signInWithOtp({
        email: g('lvm').value.trim(),
        options: {
          emailRedirectTo: location.href.split('#')[0]
        }
      });
      e(error ? error.message : 'Check your email. The link must point to a URL allowed in Auth → URL Configuration.');
    };
    if (g('lvf')) g('lvf').onclick = () => {
      localStorage.removeItem(LK);
      cfg = null;
      sb = null;
      session = null;
      grants = null;
      apply();
      render();
    };
    if (g('lvo')) g('lvo').onclick = async () => {
      await sb.auth.signOut();
      session = null;
      apply();
      render();
    };
    d.style.display = 'block';
    const first = d.querySelector('input,button');
    if (first) first.focus();
  }
  window.SEM_LIVE_OPEN = render;
  if (cfg) connect().catch(x => {
    err = x.message;
    apply();
  });else apply();
})();
})(); } catch (e) { __ds_ns.__errors.push({ path: "handoff/design_handoff_semester_launch/live.js", error: String((e && e.message) || e) }); }

